import type { GoslingSpec } from '@gosling-lang/gosling-schema';

// WHO flu (USA), rebuilt with the period coordinate system from the original `who_flu_usa.csv`.
// Supplementary Fig. S7 / paper Fig. 1A drew its ring from a hand-made file in which every date was moved
// into 2010; here `period` wraps the time axis by year instead. The years are ISO week-based (`weekBased`),
// so ISO week 1 is at 12 o'clock in every year, also when it starts in late December (2014-W01 starts on
// 2013-12-30).
//
// Time coordinate systems: the ring and the season comparison share the period system
// "year, ISO weeks", so the brush on the ring drives the comparison view; the timeline below is absolute
// time and is linked to neither.

// The ISO_SDATE column holds local (CET) midnight exported as UTC, i.e. Sunday 23:00 UTC, which falls in the
// previous ISO week. So the dates are read from the year and week columns: with `includesCalendarWeek`,
// the Monday of each ISO week is stored, as Unix seconds, in the first field (`ISO_YEAR`).
const FLU = {
    url: 'https://raw.githubusercontent.com/vanessastoiber/thesis-datasets/main/5_who-flu/who_flu_usa.csv',
    type: 'csv-time',
    dateFields: ['ISO_YEAR', 'ISO_WEEK'],
    includesCalendarWeek: true
} as const;

/** Wrap the time axis by ISO week-based year; each row's year is stored in the field `year`. */
const PERIOD = { unit: 'year', weekBased: true, newField: 'year' } as const;

const YEAR_COLOR = {
    field: 'year',
    type: 'nominal',
    domain: ['2010', '2011', '2012', '2013', '2014'],
    range: ['#C635BB', '#E5C011', '#12C340', '#1279C3', '#CC2F06'],
    title: 'Year'
} as const;

const CASES = { field: 'INF_A', type: 'quantitative', domain: [0, 14000], title: 'Cases per week' } as const;

const spec = {
    title: 'When in the year does influenza A peak?',
    subtitle: 'Weekly influenza A cases, USA, 2010 to 2014; brush the ring to compare weeks. Source: WHO FluNet',
    arrangement: 'vertical',
    views: [
        {
            arrangement: 'horizontal',
            views: [
                {
                    // --- Ring: every year on one revolution, week 1 at 12 o'clock ---
                    layout: 'circular',
                    centerRadius: 0.45,
                    tracks: [
                        {
                            alignment: 'overlay',
                            data: FLU,
                            x: { field: 'ISO_YEAR', type: 'temporal', period: PERIOD, axis: 'top' },
                            y: CASES,
                            tracks: [
                                { mark: 'line', color: { ...YEAR_COLOR, legend: true }, size: { value: 2 } },
                                // a brush in the period coordinate system: it selects weeks of every year at once
                                {
                                    mark: 'brush',
                                    x: { linkingId: 'weeks' },
                                    color: { value: 'gray' },
                                    opacity: { value: 0.12 }
                                }
                            ],
                            width: 380,
                            height: 120
                        }
                    ]
                },
                {
                    // --- Season comparison: the same period system on a linear axis, driven by the brush ---
                    tracks: [
                        {
                            title: 'Selected weeks, every year',
                            data: FLU,
                            mark: 'line',
                            x: {
                                field: 'ISO_YEAR',
                                type: 'temporal',
                                period: PERIOD,
                                axis: 'bottom',
                                linkingId: 'weeks'
                            },
                            y: { ...CASES, axis: 'left' },
                            color: { ...YEAR_COLOR, legend: true },
                            size: { value: 2 },
                            width: 420,
                            height: 380
                        }
                    ]
                }
            ]
        },
        {
            // --- Timeline: absolute time, a separate coordinate system (not linked to the period views) ---
            tracks: [
                {
                    title: 'All weeks, 2010 to 2014',
                    data: FLU,
                    mark: 'bar',
                    x: { field: 'ISO_YEAR', type: 'temporal', axis: 'bottom', domain: { interval: ['2010', '2014'] } },
                    y: CASES,
                    color: { value: 'black' },
                    size: { value: 2 },
                    width: 820,
                    height: 100
                }
            ]
        }
    ]
};

export const EX_SPEC_TEMPORAL_WHO_FLU_PERIOD = spec as unknown as GoslingSpec;
---

## Installation

### npm

```bash
# Install the embed package
npm install time-i-gram@0.1.0
```

The package is one self-contained ES module (React, PixiJS and HiGlass are bundled), so nothing else needs to be installed.
Without installing, import it from a CDN:

```js
import { embed } from 'https://cdn.jsdelivr.net/npm/time-i-gram@0.1.0/dist/index.js';
```

---

## Quick Start

### Using the React Component

```tsx
import { GoslingComponent } from 'gosling.js';

const spec = {
  title: 'Seattle Weather',
  tracks: [{
    data: {
      url: 'https://raw.githubusercontent.com/vega/vega/main/docs/data/seattle-weather.csv',
      type: 'csv-time',
      dateFields: ['date']
    },
    mark: 'bar',
    x: { field: 'date', type: 'temporal', axis: 'bottom', domain: { interval: [1325376000, 1451606400] } }, // 2012-2015 in Unix seconds
    y: { field: 'precipitation', type: 'quantitative' },
    width: 800,
    height: 200
  }]
};

function App() {
  return <GoslingComponent spec={spec} />;
}
```

### Using the Embed API

```js
import { embed } from 'time-i-gram';

const spec = { /* your time-i-gram spec */ };

// Embed in a DOM element
embed(document.getElementById('container'), spec);
```

### Using in Observable Notebooks

```js
embed = {
  const mod = await import('https://cdn.jsdelivr.net/npm/time-i-gram@0.1.0/dist/index.js');
  return mod.embed;
}
```

---

## Usage Example

### U.S. Unemployment Across Industries — Circular Overview + Linked Detail

A multi-view dashboard combining a **circular overview** (left) with **linked detail panels** (right) for exploring U.S. unemployment across five industry sectors (2000–2010). Brushing on the circular view or the timeline bar zooms all detail panels via coordinated linking. This is the editor example *Supp. S3: U.S. Unemployment Across Industries*.


```js
import { embed } from 'time-i-gram';

// Monthly unemployment by industry, 2000 to 2010 (U.S. Bureau of Labor Statistics), as published in vega-datasets
const DATA_URL = "https://raw.githubusercontent.com/vega/vega/main/docs/data/unemployment-across-industries.json";

const baseData = { type: "json-time", url: DATA_URL, dateFields: ["date"], sampleLength: 2000 };

// January 2000 to February 2010, the extent of the data
const timeDomain = { interval: ["2000-01", "2010-02"] };
const industries = ["Government", "Manufacturing", "Construction", "Information", "Finance"];
const yTitle = "Unemployed (thousands)";

// One industry as an area with a line on top; `legend` only on the last line of a panel
function industryTracks(series, legend) {
  const base = {
    data: { ...baseData },
    dataTransform: [{ type: "filter", field: "series", oneOf: [series] }],
    x: { field: "date", type: "temporal", axis: "bottom", domain: timeDomain, linkingId: "detail-link" },
    color: { field: "series", type: "nominal", domain: industries, legend, title: "Industry" },
    style: { outline: "none" }
  };
  return [
    { ...base, mark: "area", opacity: { value: 0.3 }, y: { field: "count", type: "quantitative", axis: "left" } },
    { ...base, mark: "line", size: { value: 1.5 }, y: { field: "count", type: "quantitative", axis: "left", title: yTitle } }
  ];
}

const spec = {
  title: "Which industries were hit hardest by the 2008 recession?",
  subtitle: "Unemployed persons (thousands) by industry and month, 2000 to 2010. Source: U.S. Bureau of Labor Statistics",
  arrangement: "horizontal",
  views: [
    // ── LEFT: circular overview with a brush ──
    {
      layout: "circular",
      title: "All industries (drag the brush)",
      centerRadius: 0.5, // room for the axis title and the legend in the center
      alignment: "overlay",
      width: 450,
      height: 450,
      tracks: [
        ...industries.map((series, i) => ({
          data: { ...baseData },
          dataTransform: [{ type: "filter", field: "series", oneOf: [series] }],
          x: { field: "date", type: "temporal", axis: "top", domain: timeDomain },
          // the radial axis and the legend are shared: one title and one legend, in the center
          y: { field: "count", type: "quantitative", axis: "right", ...(i === 0 ? { title: yTitle } : {}) },
          color: { field: "series", type: "nominal", domain: industries, legend: i === 0, title: "Industry" },
          mark: "line",
          width: 450,
          height: 450,
          style: { outline: "none" }
        })),
        { mark: "brush", x: { linkingId: "detail-link" }, color: { value: "steelBlue" } }
      ]
    },
    // ── RIGHT: detail panels stacked vertically, and a timeline with a brush ──
    {
      arrangement: "vertical",
      views: [
        {
          title: "Public and industrial sectors",
          alignment: "overlay",
          width: 500,
          height: 170,
          tracks: ["Government", "Manufacturing", "Construction"].flatMap((s, i, all) => industryTracks(s, i === all.length - 1))
        },
        {
          title: "Service and knowledge sectors",
          alignment: "overlay",
          width: 500,
          height: 170,
          tracks: ["Information", "Finance"].flatMap((s, i, all) => industryTracks(s, i === all.length - 1))
        },
        {
          title: "All industries (drag to select a period)",
          alignment: "overlay",
          width: 500,
          height: 60,
          tracks: [
            {
              data: { ...baseData },
              x: { field: "date", type: "temporal", axis: "bottom", domain: timeDomain },
              y: { field: "count", type: "quantitative", axis: "none" },
              color: { value: "#94a3b8" },
              mark: "bar",
              width: 500,
              height: 60,
              style: { outline: "none" }
            },
            { mark: "brush", x: { linkingId: "detail-link" }, color: { value: "steelBlue" } }
          ]
        }
      ]
    }
  ]
};

embed(document.getElementById("container"), spec);
```

