                    // means keeps the views readable and interactive
                    mark: 'line',
                    x: {
                        field: 'Time',
                        type: 'temporal',
                        period: { unit: 'week', newField: 'week' },
                        timeUnit: 'hour',
                        axis: 'top'
                    },
                    y: {
                        field: 'Value',
                        type: 'quantitative',
                        aggregate: 'mean',
                        domain: [50, 130],
                        axis: 'none',
                        title: 'Heart rate (bpm)'
                    },
                    row: { field: 'week', type: 'nominal' },
                    color: { field: 'week', type: 'nominal', legend: true, title: 'Week (outer: first)' },
                    size: { value: 1.5 },
                    width: 420,
                    height: 160
                }
            ]
        },
        {
            tracks: [
                {
                    title: 'Mean by hour of the day, all days',
                    data: HEART_RATE,
                    dataTransform: ONE_PARTICIPANT,
                    mark: 'bar',
                    x: { field: 'Time', type: 'temporal', period: 'day', timeUnit: 'hour', axis: 'bottom' },
                    y: {
                        field: 'Value',
                        type: 'quantitative',
                        aggregate: 'mean',
                        domain: [0, 130],
                        axis: 'left',
